import json, re, datetime
def _js(v):
    if isinstance(v, str):
        s = v.strip()
        if s[:1] in ('[', '('):
            try:
                return json.loads(s)
            except Exception:
                try:
                    import ast
                    return ast.literal_eval(s)
                except Exception:
                    return v
        if s[:1] == chr(123):
            try:
                return json.loads(s)
            except Exception:
                try:
                    import ast
                    return ast.literal_eval(s)
                except Exception:
                    return v
    return v
def _uf(flat):
    root = dict()
    for k in sorted(flat.keys()):
        parts = [p for p in re.split(r'[.\[\]]+', k) if p != '']
        cur = root
        for p in parts[:-1]:
            nxt = cur.get(p)
            if not isinstance(nxt, dict):
                nxt = dict()
                cur[p] = nxt
            cur = nxt
        if parts:
            cur[parts[-1]] = flat[k]
    def fix(o):
        if isinstance(o, dict):
            o2 = dict((kk, fix(vv)) for kk, vv in o.items())
            if o2 and all(str(kk).isdigit() for kk in o2.keys()):
                return [o2[kk] for kk in sorted(o2.keys(), key=lambda x: int(x))]
            return o2
        return o
    return fix(root)
def body_of(n):
    b = _js(vars.get(n + '_body'))
