ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
CUR = [('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')]
def w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(('' if h == 1 else ONES[h] + ' ') + 'yüz')
    if t:
        s.append(TENS[t])
    if o:
        s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, name in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append('bin' if (val == 1000 and q == 1) else w3(q) + ' ' + name)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)
def num(x):
    try:
        return float(str(x).replace(',', '.'))
    except Exception:
        return 0.0
def money(x, cur):
    c = int(round(abs(num(x)) * 100))
    main, sub = divmod(c, 100)
    if cur == 'TL':
        if sub:
            return words(main) + ' lira ' + words(sub) + ' kuruş'
        return words(main) + ' Türk Lirası'
    nm = dict(USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')[cur]
    sb = 'peni' if cur == 'GBP' else 'sent'
    if sub:
        return words(main) + ' ' + nm + ' ' + words(sub) + ' ' + sb
    return words(main) + ' ' + nm
def cop(phrase):
    w = phrase.strip().split(' ')[-1]
    low = words(int(w)) if w.isdigit() else w.replace('I', 'ı').replace('İ', 'i').lower()
    vow = [ch for ch in low if ch in 'aeıioöuü']
    lv = vow[-1] if vow else 'e'
    v = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[lv]
    cons = 't' if low[-1:] in list('fstkçşhp') else 'd'
    sep = "'" if (w[:1].isupper() or w[:1].isdigit()) else ''
    return phrase + sep + cons + v + 'r'
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def dsp(s):
    d = pdate(s)
    if not d:
        return ''
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)
def today():
    try:
        return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception:
        return datetime.date.today()
def dw(s):
    return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())
def norm(s):
    s = str(s or '').replace('İ', 'i').replace('I', 'ı').lower()
    for a, b in (('ı', 'i'), ('ş', 's'), ('ğ', 'g'), ('ü', 'u'), ('ö', 'o'), ('ç', 'c'), ('â', 'a')):
        s = s.replace(a, b)
    return re.sub(r'[^a-z0-9 ]', ' ', s).strip()
def clean_name(n):
    n = str(n or '').strip()
    low = norm(n)
    bad = ['talimat', 'yok say', 'ignore', 'numara', 'prompt', 'sistem', 'instruction', 'kural']
    if len(n) > 40 or any(b in low for b in bad) or re.search(r'\boku\b', low):
        return ''
    return n
