    for c in order:
        lab = c['name'] if c.get('name') else 'sonu ' + dw(c['l4']) + ' ile biten kartım'
        if lab not in ex:
            ex.append(lab)
    q = pref + 'Hangi kartınızın borcunu öğrenmek istersiniz?'
    if len(ex) >= 2:
        q += ' Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'
    elif ex:
        q += ' Örneğin, ' + ex[0] + ' diyebilirsiniz.'
    return q
