    b = _js(vars.get(n + '_body'))
    if isinstance(b, dict) and b:
        return b
    r = _js(vars.get(n + '_response'))
    if isinstance(r, dict):
        d = _js(r.get('data'))
        if isinstance(d, dict) and d:
            return d
    pre = n + '_response.data.'
    flat = dict((k[len(pre):], v) for k, v in vars.items() if isinstance(k, str) and k.startswith(pre) and v not in (None, ''))
    if flat:
        return _uf(flat)
    return dict()
