            vars['say_text'] = 'Başka hangi konuda yardımcı olabilirim?'
            st = 'announce'
        elif str(vars.get('email_state') or '') == '':
            vars['stage'] = 'offer'
            vars['after_email'] = 'reading'
            clear('fetch_email')
            st = 'email'
        else:
            o = offer_text()
            vars['stage'] = 'offer' if o else 'none'
            vars['say_text'] = o or 'Başka hangi konuda yardımcı olabilirim?'
            st = 'announce'
except Exception:
    st = 'error'
vars['bal_state'] = st

